// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import { FileTree } from "@/registry/erbium/blocks/file-tree";
import type { Meta, StoryObj } from "@storybook/react";
import OverviewExample from "./variants/overview";

import CompositionExample from "./variants/composition";

import ChangesExample from "./variants/changes";


const meta = {
  component: FileTree,
  parameters: {
    docs: { description: { component: "## Usage

```tsx
import { FileTree, useFileTree } from "@/registry/erbium/blocks/file-tree";

const { model } = useFileTree({
  paths: ["src/app.tsx", "package.json", "empty/"],
  initialExpansion: "open",
  onSelectionChange: setSelectedPaths,
});

<FileTree model={model} aria-label="Workspace files" />;
```

Paths infer the directory hierarchy. A trailing slash represents an explicit directory, including an empty one. Pierre handles virtualized rows, keyboard navigation, expansion, and selection; Erbium owns typography, colors, density, and the sidebar navigation surface.

## Model lifecycle

`useFileTree` creates one stable model and cleans it up on unmount. Options and callbacks are construction-time configuration; changes to the options object do not update the model. Keep callbacks independent of stale render state. Update files through `model.add`, `remove`, `move`, `batch`, or `resetPaths`; update status through `setGitStatus`. Use item handles from `model.getItem(path)` for expansion or selection. Read selection through Pierre’s `useFileTreeSelection` hook if needed.

Search uses `model.openSearch`, `setSearch`, and search-match navigation. Enable built-in search with `search: true`. Renaming and drag/drop are opt-in model settings; persistence and filesystem authorization belong to the consumer. Lazy directory loading can compose around directory handles and subscriptions; FileTree does not fetch files itself.

## Composition

```tsx
<FileTree model={model} aria-label="Project files">
  <FileTreeHeader>
    <FileTreeTitle>Project files</FileTreeTitle>
    <FileTreeActions>
      <Button onClick={() => model.openSearch()}>Find file</Button>
    </FileTreeActions>
  </FileTreeHeader>
  <FileTreeContent className="h-96" />
</FileTree>
```

The default is a content-only tree, bounded to a 20rem viewport. Supplying children replaces that layout. Header, title, and actions follow the sidebar’s compact navigation styling. Place the tree inside `SidebarGroupContent` to compose it with other navigation. Give the content enough height for virtualization; customize its height through `FileTreeContent`. `renderContextMenu` and `preloadedData` forward Pierre’s React composition and SSR contracts. Supply accessible names and keyboard behavior for custom menu controls. Pass a tree label on `FileTreeContent` when customizing the inner tree.

## Design ownership

There are no theme, injected CSS, density, or row-height options. The tree follows the application’s scheme and sidebar surface, hover, and active colors, with neutral file icons and semantic focus and Git-status colors. The model remains Pierre-compatible so downstream developers can use its typed operations without a second controller API." } },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof FileTree>;

export default { ...meta, title: "Blocks/File Tree",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: "import { useState } from "react";
import { FileTree, useFileTree } from "@/registry/erbium/blocks/file-tree";
import { paths } from "../examples/paths";

export default function FileTreeExample() {
  const [selected, setSelected] = useState<readonly string[]>([]);

  const { model } = useFileTree({
    initialExpansion: "open",
    onSelectionChange: setSelected,
    paths,
  });

  return (
    <div className="grid w-80 gap-3">
      <FileTree model={model} aria-label="Workspace files" />
      <p className="text-caption text-muted-foreground" aria-live="polite">
        {selected.length ? selected.join(", ") : "Select a file or directory."}
      </p>
    </div>
  );
}
" },
    },
  },
  render: OverviewExample,
};

export const Composition: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: "import {
  FileTree,
  useFileTree,
  FileTreeHeader,
  FileTreeTitle,
  FileTreeActions,
  FileTreeContent,
} from "@/registry/erbium/blocks/file-tree";
import { Button } from "@/registry/erbium/ui/button";
import {
  Sidebar,
  SidebarProvider,
  SidebarContent,
  SidebarGroup,
  SidebarGroupContent,
} from "@/registry/erbium/ui/sidebar";
import { paths } from "../examples/paths";

export default function FileTreeCompositionExample() {
  const { model } = useFileTree({ initialExpansion: 1, paths, search: true });

  return (
    <SidebarProvider className="min-h-0 w-80">
      <Sidebar collapsible="none" className="w-full">
        <SidebarContent>
          <SidebarGroup>
            <SidebarGroupContent>
              <FileTree model={model} aria-label="Project files">
                <FileTreeHeader>
                  <FileTreeTitle>Project files</FileTreeTitle>
                  <FileTreeActions>
                    <Button
                      variant="ghost"
                      size="xs"
                      onClick={() => {
                        model.openSearch();
                      }}
                    >
                      Find file
                    </Button>
                  </FileTreeActions>
                </FileTreeHeader>
                <FileTreeContent className="h-96" />
              </FileTree>
            </SidebarGroupContent>
          </SidebarGroup>
        </SidebarContent>
      </Sidebar>
    </SidebarProvider>
  );
}
" },
    },
  },
  render: CompositionExample,
};

export const Changes: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: "import {
  FileTree,
  useFileTree,
  FileTreeHeader,
  FileTreeTitle,
  FileTreeActions,
  FileTreeContent,
} from "@/registry/erbium/blocks/file-tree";
import { Button } from "@/registry/erbium/ui/button";
import { paths } from "../examples/paths";

export default function FileTreeChangesExample() {
  const { model } = useFileTree({
    gitStatus: [
      { path: "src/blocks/file-view.tsx", status: "added" },
      { path: "src/styles/surfaces.css", status: "modified" },
    ],
    initialExpansion: "open",
    paths,
  });

  return (
    <FileTree model={model} className="w-80" aria-label="Changed project files">
      <FileTreeHeader>
        <FileTreeTitle>Changes</FileTreeTitle>
        <FileTreeActions>
          <Button
            variant="ghost"
            size="xs"
            onClick={() => {
              model.add("src/blocks/file-tree.tsx");
            }}
          >
            Add file
          </Button>
        </FileTreeActions>
      </FileTreeHeader>
      <FileTreeContent />
    </FileTree>
  );
}
" },
    },
  },
  render: ChangesExample,
};

